spec.expr:
max by(instance,server,datname) ( pg_settings_max_connections{instance=~"$instance_db:.*"})
- on(instance,server) group_left(datname)
sum by(instance,server,datname) 
    (pg_stat_activity_count{
        instance=~"$instance_db:.*"
        }
    )

(
  100
    *
  (
    sum(
      pg_stat_activity_count{
        instance=~"$instance_db:.*"
      }
    ) by(instance,datname)
      -
    (
      (
        sum(
          pg_stat_activity_count{
            instance=~"$instance_db:.*"
          } offset $interval
        ) by(instance,datname)
      )
    )
  )
)
  /
clamp_min (
  (
    sum(
      pg_stat_activity_count{
            instance=~"$instance_db:.*"
      } offset $interval
    ) by(instance,datname)
  )  ,
  1
)

(
  100
    *
  (
    sum(
      pg_stat_activity_count{
        instance=~"$instance_db:.*"
      }
    ) by(instance, server,datname)
      -
    (
      (
        sum(
          pg_stat_activity_count{           instance=~"$instance_db:.*"
          } offset $interval
        ) by(instance, server,datname)
      ) 
    )
  )
)
  /
clamp_min (
  (
    sum(
      pg_stat_activity_count{           instance=~"$instance_db:.*"
      } offset $interval
    ) by(instance, server,datname)
  ) ,
